import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"42、【益】 震下巽上","description":"温公易说 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"温公易说 - 42、【益】 震下巽上"},"headers":[],"relativePath":"zh/classics/wengong/043.md","filePath":"zh/classics/wengong/043.md"}'),n={name:"zh/classics/wengong/043.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><h3 id="彖曰-益-损上益下-民说无疆。自上下下-其道大光。利有攸往-中正有庆。利渉大川-木道乃行。益动而巽-日进无疆。天施地生-其益无方。凡益之道-与时偕行。" tabindex="-1">彖曰：益，损上益下，民说无疆。自上下下，其道大光。利有攸往，中正有庆。利渉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。 <a class="header-anchor" href="#彖曰-益-损上益下-民说无疆。自上下下-其道大光。利有攸往-中正有庆。利渉大川-木道乃行。益动而巽-日进无疆。天施地生-其益无方。凡益之道-与时偕行。" aria-label="Permalink to “彖曰：益，损上益下，民说无疆。自上下下，其道大光。利有攸往，中正有庆。利渉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。”">​</a></h3><h3 id="象曰-风雷-益。君子以见善则迁-有过则改。" tabindex="-1">象曰：风雷，益。君子以见善则迁，有过则改。 <a class="header-anchor" href="#象曰-风雷-益。君子以见善则迁-有过则改。" aria-label="Permalink to “象曰：风雷，益。君子以见善则迁，有过则改。”">​</a></h3><h3 id="初九-利用为大作-元吉-无咎-象曰-元吉无咎-下不厚事也。" tabindex="-1">初九：利用为大作，元吉，无咎 象曰：元吉无咎，下不厚事也。 <a class="header-anchor" href="#初九-利用为大作-元吉-无咎-象曰-元吉无咎-下不厚事也。" aria-label="Permalink to “初九：利用为大作，元吉，无咎 象曰：元吉无咎，下不厚事也。”">​</a></h3><h3 id="六二-或益之-十朋之龟-弗克违-永贞吉。王用享于帝-吉-象曰-或益之-自外来也。" tabindex="-1">六二：或益之，十朋之龟，弗克违，永贞吉。王用享于帝，吉 象曰：或益之，自外来也。 <a class="header-anchor" href="#六二-或益之-十朋之龟-弗克违-永贞吉。王用享于帝-吉-象曰-或益之-自外来也。" aria-label="Permalink to “六二：或益之，十朋之龟，弗克违，永贞吉。王用享于帝，吉 象曰：或益之，自外来也。”">​</a></h3><h3 id="六三-益之用凶事-无咎-有孚。中行告公-用圭-象曰-益用凶事故有之也。" tabindex="-1">六三：益之用凶事，无咎，有孚。中行告公，用圭 象曰：益用凶事故有之也。 <a class="header-anchor" href="#六三-益之用凶事-无咎-有孚。中行告公-用圭-象曰-益用凶事故有之也。" aria-label="Permalink to “六三：益之用凶事，无咎，有孚。中行告公，用圭 象曰：益用凶事故有之也。”">​</a></h3><h3 id="六四-中行告公-从利为依。迁国-象曰-告公从以益志也。" tabindex="-1">六四：中行告公，从利为依。迁国 象曰：告公从以益志也。 <a class="header-anchor" href="#六四-中行告公-从利为依。迁国-象曰-告公从以益志也。" aria-label="Permalink to “六四：中行告公，从利为依。迁国 象曰：告公从以益志也。”">​</a></h3><h3 id="九五-有孚惠心-勿问-元吉。有孚惠我德-象曰-有孚惠心-勿问之矣。惠我德-大得志也。" tabindex="-1">九五：有孚惠心，勿问，元吉。有孚惠我德 象曰：有孚惠心，勿问之矣。惠我德，大得志也。 <a class="header-anchor" href="#九五-有孚惠心-勿问-元吉。有孚惠我德-象曰-有孚惠心-勿问之矣。惠我德-大得志也。" aria-label="Permalink to “九五：有孚惠心，勿问，元吉。有孚惠我德 象曰：有孚惠心，勿问之矣。惠我德，大得志也。”">​</a></h3><p>惠心者何？惠之所施，孚于心然后善也。夫人坠于絶壑而遗之珠玉，寝疾垂死而馈之酒肉，其物非不美也，而人不以德者何也？非其心之所欲也。</p><h3 id="上九-莫益之-或击之。立心勿恒-凶-象曰-莫益之-偏辞也。或击之-自外来也。" tabindex="-1">上九：莫益之，或击之。立心勿恒，凶 象曰：莫益之，偏辞也。或击之，自外来也。 <a class="header-anchor" href="#上九-莫益之-或击之。立心勿恒-凶-象曰-莫益之-偏辞也。或击之-自外来也。" aria-label="Permalink to “上九：莫益之，或击之。立心勿恒，凶 象曰：莫益之，偏辞也。或击之，自外来也。”">​</a></h3><p>上九立心勿恒，凶何也？戒人勿以求益为常心也。莫益之，偏辞者何也？知益于已而不知恕于人之谓也。</p>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
